require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../repositories/userPDO.php';$pdo=openDatabase();$admin=requireLogin($pdo);requireRole($admin,['Administrator']);
$q=trim((string)($_GET['q']??''));$role=(string)($_GET['role']??'');$status=(string)($_GET['status']??'');if(!in_array($role,['','Student','Tutor','Administrator'],true)||!in_array($status,['','Active','Inactive'],true)){http_response_code(400);exit('Invalid filter.');}$users=searchUsers($pdo,$q,$role,$status);require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/nav.php';?><main class="container py-4"><h1>Manage Users</h1><form method="get" class="row g-2 mb-3"><div class="col"><input class="form-control" name="q" placeholder="Search name or email" value="<?=htmlspecialchars($q,ENT_QUOTES,'UTF-8')?>"></div><div class="col"><select class="form-select" name="role"><option value="">All roles</option><?php foreach(['Student','Tutor','Administrator'] as $v):?><option <?=$role===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="col"><select class="form-select" name="status"><option value="">All statuses</option><?php foreach(['Active','Inactive'] as $v):?><option <?=$status===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="col-auto"><button class="btn btn-primary">Search</button></div></form><table class="table table-striped"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Manage</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=htmlspecialchars($u['full_name'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($u['email'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($u['role'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($u['status'],ENT_QUOTES,'UTF-8')?></td><td><a href="/php/manage-user.php?user_id=<?=(int)$u['user_id']?>">Manage</a></td></tr><?php endforeach;?></tbody></table><?php if(!$users):?><p>No matching accounts.</p><?php endif;?></main><?php require __DIR__.'/../includes/footer.php';?>
